    'CREATE TABLE [agent_events] (\n    [id] BIGINT IDENTITY(1,1) NOT NULL,\n    [run_agent_id] BIGINT NOT NULL,\n    [ts] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,\n    [event_type] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,\n    [phase] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2,\n    [payload_json] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2,\n    CONSTRAINT [pk_agent_events] PRIMARY KEY CLUSTERED ([id])\n)',
