    'CREATE TABLE [auth_audit_events] (\n    [id] BIGINT IDENTITY(1,1) NOT NULL,\n    [at] NVARCHAR(850) COLLATE Latin1_General_100_BIN2 NOT NULL,\n    [actor_email] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,\n    [action] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,\n    [target] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,\n    [detail_json] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2,\n    CONSTRAINT [pk_auth_audit_events] PRIMARY KEY CLUSTERED ([id])\n)',
