    'CREATE TRIGGER [auth_users_on_delete] ON [auth_users] INSTEAD OF DELETE AS\nBEGIN\n    SET NOCOUNT ON;\n    DELETE c FROM [auth_sessions] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[email] = c.[email]);\n    DELETE p FROM [auth_users] p WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[email] = p.[email]);\nEND',
    'CREATE TRIGGER [concept_nodes_on_delete] ON [concept_nodes] INSTEAD OF DELETE AS\nBEGIN\n    SET NOCOUNT ON;\n    DELETE c FROM [concept_edges] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[concept_uuid] = c.[child_uuid]);\n    DELETE c FROM [concept_edges] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[concept_uuid] = c.[parent_uuid]);\n    UPDATE c SET [parent_uuid] = NULL FROM [concept_nodes] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[concept_uuid] = c.[parent_uuid]);\n    DELETE c FROM [concept_render_aliases] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[concept_uuid] = c.[concept_uuid]);\n    DELETE c FROM [concept_semantic_addresses] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[concept_uuid] = c.[concept_uuid]);\n    DELETE c FROM [concept_targets] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[concept_uuid] = c.[concept_uuid]);\n    DELETE c FROM [fact_source_receipts] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[concept_uuid] = c.[concept_uuid]);\n    DELETE c FROM [gold_concept_facts] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[concept_uuid] = c.[concept_uuid]);\n    DELETE c FROM [run_concept_facts] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[concept_uuid] = c.[concept_uuid]);\n    DELETE p FROM [concept_nodes] p WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[concept_uuid] = p.[concept_uuid]);\nEND',
    'CREATE TRIGGER [concept_templates_on_delete] ON [concept_templates] INSTEAD OF DELETE AS\nBEGIN\n    SET NOCOUNT ON;\n    DELETE c FROM [concept_nodes] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[template_id] = c.[template_id]);\n    DELETE p FROM [concept_templates] p WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[template_id] = p.[template_id]);\nEND',
    'CREATE TRIGGER [eval_benchmarks_on_delete] ON [eval_benchmarks] INSTEAD OF DELETE AS\nBEGIN\n    SET NOCOUNT ON;\n    DELETE c FROM [eval_benchmark_templates] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[id] = c.[benchmark_id]);\n    DELETE c FROM [eval_scores] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[id] = c.[benchmark_id]);\n    UPDATE c SET [benchmark_id] = NULL FROM [eval_suite_docs] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[id] = c.[benchmark_id]);\n    DELETE c FROM [gold_concept_facts] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[id] = c.[benchmark_id]);\n    DELETE c FROM [gold_note_texts] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[id] = c.[benchmark_id]);\n    UPDATE c SET [benchmark_id] = NULL FROM [repeat_groups] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[id] = c.[benchmark_id]);\n    UPDATE c SET [benchmark_id] = NULL FROM [runs] c WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[id] = c.[benchmark_id]);\n    DELETE p FROM [eval_benchmarks] p WHERE EXISTS (SELECT 1 FROM deleted d WHERE d.[id] = p.[id]);\nEND',
