    "CREATE TRIGGER [runs_activity_insert] ON [runs] AFTER INSERT AS\nBEGIN\n    SET NOCOUNT ON;\n    UPDATE r SET updated_at = COALESCE(FORMAT(SWITCHOFFSET(TRY_CONVERT(DATETIMEOFFSET, i.created_at), '+00:00'), 'yyyy-MM-dd''T''HH:mm:ss.fff''Z''', 'en-US'), i.created_at)\n    FROM [runs] r JOIN inserted i ON i.id = r.id WHERE i.updated_at = N'';\nEND",
    "CREATE TRIGGER [runs_activity_update] ON [runs] AFTER UPDATE AS\nBEGIN\n    SET NOCOUNT ON;\n    DECLARE @now NVARCHAR(40) = FORMAT(SYSUTCDATETIME(), 'yyyy-MM-dd''T''HH:mm:ss.fff''Z''', 'en-US');\n    UPDATE r SET updated_at = @now FROM [runs] r JOIN inserted i ON i.id = r.id\n    JOIN deleted d ON d.id = i.id WHERE i.updated_at = d.updated_at AND i.updated_at <> @now;\nEND",
